-- DEV-001: signed outbound webhooks. Lifecycle events are captured by triggers in
-- the transaction that changes the record, so every door (forms, JSON, bill runs,
-- move-in, scheduled jobs and agents' approved proposals) emits the same event
-- once, with the DEV-005 metadata of the relevant records copied at event time.
-- Events are kept only while an endpoint is active; restores (rer import) and
-- privacy erasure write without emitting. Payloads carry ids, states, dates and
-- amounts, never names, email or postal addresses or free-text reasons.
CREATE TABLE nc_webhook_endpoints(
 id TEXT PRIMARY KEY,url TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',
 events_json TEXT NOT NULL CHECK(json_valid(events_json) AND json_type(events_json)='array'),
 status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','disabled')),
 failure_open INTEGER NOT NULL DEFAULT 0 CHECK(failure_open IN (0,1)),
 revision INTEGER NOT NULL DEFAULT 1 CHECK(typeof(revision)='integer' AND revision>0),
 created_by TEXT NOT NULL,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE nc_webhook_secrets(
 id TEXT PRIMARY KEY,endpoint_id TEXT NOT NULL REFERENCES nc_webhook_endpoints(id),sealed TEXT NOT NULL,
 created_by TEXT NOT NULL,created_at INTEGER NOT NULL,expires_at INTEGER);
CREATE INDEX nc_webhook_secrets_endpoint ON nc_webhook_secrets(endpoint_id,created_at);
CREATE TABLE nc_webhook_events(
 seq INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT NOT NULL UNIQUE,kind TEXT NOT NULL,customer_id TEXT REFERENCES nc_customers(id),record_id TEXT NOT NULL,
 payload_json TEXT NOT NULL CHECK(json_valid(payload_json)),created_at INTEGER NOT NULL);
CREATE INDEX nc_webhook_events_record ON nc_webhook_events(kind,record_id);
CREATE TABLE nc_webhook_deliveries(
 seq INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT NOT NULL UNIQUE,event_id TEXT NOT NULL REFERENCES nc_webhook_events(id),
 endpoint_id TEXT NOT NULL REFERENCES nc_webhook_endpoints(id),replay_of TEXT REFERENCES nc_webhook_deliveries(id),requested_by TEXT,
 status TEXT NOT NULL CHECK(status IN ('pending','delivered','failed')),attempts INTEGER NOT NULL DEFAULT 0 CHECK(attempts>=0),
 next_attempt_at INTEGER NOT NULL,last_status INTEGER,last_outcome TEXT,delivered_at INTEGER,created_at INTEGER NOT NULL);
CREATE INDEX nc_webhook_deliveries_due ON nc_webhook_deliveries(status,next_attempt_at);
CREATE INDEX nc_webhook_deliveries_endpoint ON nc_webhook_deliveries(endpoint_id,seq);
CREATE TABLE nc_webhook_attempts(
 delivery_id TEXT NOT NULL REFERENCES nc_webhook_deliveries(id),attempt INTEGER NOT NULL CHECK(attempt>0),at INTEGER NOT NULL,
 outcome TEXT NOT NULL CHECK(outcome IN ('delivered','http_error','network_error','no_signing_secret')),http_status INTEGER,duration_ms INTEGER NOT NULL,
 PRIMARY KEY(delivery_id,attempt));
CREATE TABLE nc_entitlement_summaries(customer_id TEXT PRIMARY KEY REFERENCES nc_customers(id),summary_json TEXT NOT NULL CHECK(json_valid(summary_json)),event_id TEXT,updated_at INTEGER NOT NULL);
CREATE TABLE nc_entitlement_dirty(customer_id TEXT PRIMARY KEY REFERENCES nc_customers(id),marked_at INTEGER NOT NULL);
CREATE TRIGGER nc_webhook_endpoints_identity BEFORE UPDATE OF id,url,created_by,created_at ON nc_webhook_endpoints WHEN NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) BEGIN SELECT RAISE(ABORT,'nectar_immutable'); END;
CREATE TRIGGER nc_webhook_endpoints_keep BEFORE DELETE ON nc_webhook_endpoints WHEN NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) BEGIN SELECT RAISE(ABORT,'nectar_immutable'); END;
CREATE TRIGGER nc_webhook_secrets_content BEFORE UPDATE OF id,endpoint_id,sealed,created_by,created_at ON nc_webhook_secrets WHEN NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) BEGIN SELECT RAISE(ABORT,'nectar_immutable'); END;
CREATE TRIGGER nc_webhook_secrets_keep BEFORE DELETE ON nc_webhook_secrets WHEN NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) BEGIN SELECT RAISE(ABORT,'nectar_immutable'); END;
CREATE TRIGGER nc_webhook_events_immutable BEFORE UPDATE ON nc_webhook_events WHEN NOT EXISTS(SELECT 1 FROM nc_privacy_context) AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) BEGIN SELECT RAISE(ABORT,'nectar_immutable'); END;
CREATE TRIGGER nc_webhook_events_keep BEFORE DELETE ON nc_webhook_events WHEN NOT EXISTS(SELECT 1 FROM nc_privacy_context) AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) BEGIN SELECT RAISE(ABORT,'nectar_immutable'); END;
CREATE TRIGGER nc_webhook_deliveries_identity BEFORE UPDATE OF id,event_id,endpoint_id,replay_of,requested_by,created_at ON nc_webhook_deliveries WHEN NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) BEGIN SELECT RAISE(ABORT,'nectar_immutable'); END;
CREATE TRIGGER nc_webhook_deliveries_keep BEFORE DELETE ON nc_webhook_deliveries WHEN NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) BEGIN SELECT RAISE(ABORT,'nectar_immutable'); END;
CREATE TRIGGER nc_webhook_attempts_immutable BEFORE UPDATE ON nc_webhook_attempts WHEN NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) BEGIN SELECT RAISE(ABORT,'nectar_immutable'); END;
CREATE TRIGGER nc_webhook_attempts_keep BEFORE DELETE ON nc_webhook_attempts WHEN NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) BEGIN SELECT RAISE(ABORT,'nectar_immutable'); END;
CREATE TRIGGER nc_webhook_events_generation_insert AFTER insert ON nc_webhook_events BEGIN UPDATE nc_privacy_generation SET value=value+1 WHERE id=1; END;
CREATE TRIGGER nc_webhook_events_generation_update AFTER update ON nc_webhook_events BEGIN UPDATE nc_privacy_generation SET value=value+1 WHERE id=1; END;
CREATE TRIGGER nc_webhook_events_generation_delete AFTER delete ON nc_webhook_events BEGIN UPDATE nc_privacy_generation SET value=value+1 WHERE id=1; END;
CREATE TRIGGER nc_entitlement_summaries_generation_insert AFTER insert ON nc_entitlement_summaries BEGIN UPDATE nc_privacy_generation SET value=value+1 WHERE id=1; END;
CREATE TRIGGER nc_entitlement_summaries_generation_update AFTER update ON nc_entitlement_summaries BEGIN UPDATE nc_privacy_generation SET value=value+1 WHERE id=1; END;
CREATE TRIGGER nc_entitlement_summaries_generation_delete AFTER delete ON nc_entitlement_summaries BEGIN UPDATE nc_privacy_generation SET value=value+1 WHERE id=1; END;
CREATE TRIGGER nc_entitlement_dirty_generation_insert AFTER insert ON nc_entitlement_dirty BEGIN UPDATE nc_privacy_generation SET value=value+1 WHERE id=1; END;
CREATE TRIGGER nc_entitlement_dirty_generation_update AFTER update ON nc_entitlement_dirty BEGIN UPDATE nc_privacy_generation SET value=value+1 WHERE id=1; END;
CREATE TRIGGER nc_entitlement_dirty_generation_delete AFTER delete ON nc_entitlement_dirty BEGIN UPDATE nc_privacy_generation SET value=value+1 WHERE id=1; END;
-- A new event fans out to every active endpoint subscribed to its kind; a new delivery is due at once.
CREATE TRIGGER nc_webhook_events_fanout AFTER INSERT ON nc_webhook_events WHEN NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) BEGIN
 INSERT INTO nc_webhook_deliveries(id,event_id,endpoint_id,status,attempts,next_attempt_at,created_at)
 SELECT 'whd_'||lower(hex(randomblob(12))),NEW.id,e.id,'pending',0,0,NEW.created_at FROM nc_webhook_endpoints e
 WHERE e.status='active' AND EXISTS(SELECT 1 FROM json_each(e.events_json) j WHERE j.value IN ('*',NEW.kind));
END;
CREATE TRIGGER nc_webhook_customer_created AFTER INSERT ON nc_customers WHEN NOT EXISTS(SELECT 1 FROM nc_privacy_context) AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) AND EXISTS(SELECT 1 FROM nc_webhook_endpoints WHERE status='active') BEGIN
 INSERT INTO nc_webhook_events(id,kind,customer_id,record_id,payload_json,created_at)
 SELECT e.eid,'customer.created',NEW.id,NEW.id,json_object('id',e.eid,'object','event','type','customer.created','created',e.ms/1000,'data',json_object('object',json_object('id',NEW.id,'object','customer','external_id',NEW.external_id,'status',NEW.status,'origin',NEW.origin,'language',NEW.language,'billing_entity_id',NEW.billing_entity_id),'metadata',json_object('customer',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='customer' AND record_id=NEW.id ORDER BY revision DESC LIMIT 1),'{}'))))),e.ms
 FROM (SELECT 'evt_'||lower(hex(randomblob(12))) AS eid,CAST((julianday('now')-2440587.5)*86400000 AS INTEGER) AS ms) e;
END;
CREATE TRIGGER nc_webhook_customer_updated AFTER UPDATE ON nc_customers WHEN OLD.revision IS NOT NEW.revision AND NEW.erased_at IS NULL AND NOT EXISTS(SELECT 1 FROM nc_privacy_context) AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) AND EXISTS(SELECT 1 FROM nc_webhook_endpoints WHERE status='active') BEGIN
 INSERT INTO nc_webhook_events(id,kind,customer_id,record_id,payload_json,created_at)
 SELECT e.eid,'customer.updated',NEW.id,NEW.id,json_object('id',e.eid,'object','event','type','customer.updated','created',e.ms/1000,'data',json_object('object',json_object('id',NEW.id,'object','customer','external_id',NEW.external_id,'status',NEW.status,'origin',NEW.origin,'language',NEW.language,'billing_entity_id',NEW.billing_entity_id),'metadata',json_object('customer',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='customer' AND record_id=NEW.id ORDER BY revision DESC LIMIT 1),'{}'))))),e.ms
 FROM (SELECT 'evt_'||lower(hex(randomblob(12))) AS eid,CAST((julianday('now')-2440587.5)*86400000 AS INTEGER) AS ms) e;
END;
CREATE TRIGGER nc_webhook_subscription_created AFTER INSERT ON nc_subscriptions WHEN NOT EXISTS(SELECT 1 FROM nc_privacy_context) AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) AND EXISTS(SELECT 1 FROM nc_webhook_endpoints WHERE status='active') BEGIN
 INSERT INTO nc_webhook_events(id,kind,customer_id,record_id,payload_json,created_at)
 SELECT e.eid,'subscription.created',NEW.customer_id,NEW.id,json_object('id',e.eid,'object','event','type','subscription.created','created',e.ms/1000,'data',json_object('object',json_object('id',NEW.id,'object','subscription','customer_id',NEW.customer_id,'external_id',NEW.external_id,'start_date',NEW.start_date,'trial_end',NEW.trial_end,'trial_outcome',NEW.trial_outcome,'end_date',NEW.end_date,'contract_end_date',NEW.contract_end_date,'billing_mode',NEW.billing_mode,'origin',NEW.origin),'metadata',json_object('customer',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='customer' AND record_id=NEW.customer_id ORDER BY revision DESC LIMIT 1),'{}')),'subscription',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='subscription' AND record_id=NEW.id ORDER BY revision DESC LIMIT 1),'{}'))))),e.ms
 FROM (SELECT 'evt_'||lower(hex(randomblob(12))) AS eid,CAST((julianday('now')-2440587.5)*86400000 AS INTEGER) AS ms) e;
END;
