 FROM (SELECT 'evt_'||lower(hex(randomblob(12))) AS eid,CAST((julianday('now')-2440587.5)*86400000 AS INTEGER) AS ms) e;
END;
CREATE TRIGGER nc_webhook_subscription_canceled AFTER UPDATE OF end_date ON nc_subscriptions WHEN OLD.end_date IS NULL AND NEW.end_date IS NOT NULL AND NOT EXISTS(SELECT 1 FROM nc_privacy_context) AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) AND EXISTS(SELECT 1 FROM nc_webhook_endpoints WHERE status='active') BEGIN
 INSERT INTO nc_webhook_events(id,kind,customer_id,record_id,payload_json,created_at)
