 FROM (SELECT 'evt_'||lower(hex(randomblob(12))) AS eid,CAST((julianday('now')-2440587.5)*86400000 AS INTEGER) AS ms) e;
END;
CREATE TRIGGER nc_webhook_subscription_pause AFTER INSERT ON nc_subscription_lifecycle WHEN NEW.kind='pause' AND NOT EXISTS(SELECT 1 FROM nc_privacy_context) AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) AND EXISTS(SELECT 1 FROM nc_webhook_endpoints WHERE status='active') BEGIN
 INSERT INTO nc_webhook_events(id,kind,customer_id,record_id,payload_json,created_at)
 SELECT e.eid,'subscription.paused',s.customer_id,s.id,json_object('id',e.eid,'object','event','type','subscription.paused','created',e.ms/1000,'data',json_object('object',json_object('id',s.id,'object','subscription','customer_id',s.customer_id,'external_id',s.external_id,'billing_mode',s.billing_mode,'transition',json_object('id',NEW.id,'kind',NEW.kind,'effective_date',NEW.effective_date,'until_date',NEW.until_date,'access',NEW.access)),'metadata',json_object('customer',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='customer' AND record_id=s.customer_id ORDER BY revision DESC LIMIT 1),'{}')),'subscription',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='subscription' AND record_id=s.id ORDER BY revision DESC LIMIT 1),'{}'))))),e.ms
 FROM (SELECT 'evt_'||lower(hex(randomblob(12))) AS eid,CAST((julianday('now')-2440587.5)*86400000 AS INTEGER) AS ms) e, nc_subscriptions s
 WHERE s.id=NEW.subscription_id;
END;
