 FROM (SELECT 'evt_'||lower(hex(randomblob(12))) AS eid,CAST((julianday('now')-2440587.5)*86400000 AS INTEGER) AS ms) e, nc_subscriptions s
 WHERE s.id=NEW.subscription_id;
END;
