CREATE TRIGGER nc_webhook_invoice_created AFTER INSERT ON nc_invoices WHEN NEW.status IN ('draft','approved','issued') AND NOT EXISTS(SELECT 1 FROM nc_privacy_context) AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) AND EXISTS(SELECT 1 FROM nc_webhook_endpoints WHERE status='active') BEGIN
 INSERT INTO nc_webhook_events(id,kind,customer_id,record_id,payload_json,created_at)
 SELECT e.eid,'invoice.created',NEW.customer_id,NEW.id,json_object('id',e.eid,'object','event','type','invoice.created','created',e.ms/1000,'data',json_object('object',json_object('id',NEW.id,'object','invoice','number',NEW.number,'customer_id',NEW.customer_id,'subscription_id',NEW.subscription_id,'status',NEW.status,'period_start',NEW.period_start,'period_end',NEW.period_end,'issue_date',NEW.issue_date,'due_date',NEW.due_date,'subtotal_cents',NEW.subtotal_cents,'tax_cents',NEW.tax_cents,'total_cents',NEW.total_cents,'currency',NEW.currency,'billing_entity_id',NEW.billing_entity_id),'metadata',json_object('customer',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='customer' AND record_id=NEW.customer_id ORDER BY revision DESC LIMIT 1),'{}')),'subscription',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='subscription' AND record_id=NEW.subscription_id ORDER BY revision DESC LIMIT 1),'{}')),'invoice',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='invoice' AND record_id=NEW.id ORDER BY revision DESC LIMIT 1),'{}')),'prices',json(COALESCE((SELECT json_group_object(p.price_id, json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='price' AND record_id=p.price_id ORDER BY revision DESC LIMIT 1),'{}'))) FROM (SELECT DISTINCT price_id FROM nc_invoice_lines WHERE invoice_id=NEW.id AND price_id IS NOT NULL ORDER BY price_id) p),'{}'))))),e.ms
 FROM (SELECT 'evt_'||lower(hex(randomblob(12))) AS eid,CAST((julianday('now')-2440587.5)*86400000 AS INTEGER) AS ms) e;
END;
