 FROM (SELECT 'evt_'||lower(hex(randomblob(12))) AS eid,CAST((julianday('now')-2440587.5)*86400000 AS INTEGER) AS ms) e;
END;
CREATE TRIGGER nc_webhook_invoice_paid_allocation AFTER INSERT ON nc_allocations WHEN NOT EXISTS(SELECT 1 FROM nc_privacy_context) AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) AND EXISTS(SELECT 1 FROM nc_webhook_endpoints WHERE status='active') BEGIN
 INSERT INTO nc_webhook_events(id,kind,customer_id,record_id,payload_json,created_at)
 SELECT e.eid,'invoice.paid',i.customer_id,i.id,json_object('id',e.eid,'object','event','type','invoice.paid','created',e.ms/1000,'data',json_object('object',json_object('id',i.id,'object','invoice','number',i.number,'customer_id',i.customer_id,'subscription_id',i.subscription_id,'status',i.status,'period_start',i.period_start,'period_end',i.period_end,'issue_date',i.issue_date,'due_date',i.due_date,'subtotal_cents',i.subtotal_cents,'tax_cents',i.tax_cents,'total_cents',i.total_cents,'currency',i.currency,'billing_entity_id',i.billing_entity_id,'amount_paid_cents',COALESCE((SELECT SUM(amount_cents) FROM nc_allocations WHERE invoice_id=i.id),0),'amount_remaining_cents',0),'metadata',json_object('customer',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='customer' AND record_id=i.customer_id ORDER BY revision DESC LIMIT 1),'{}')),'subscription',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='subscription' AND record_id=i.subscription_id ORDER BY revision DESC LIMIT 1),'{}')),'invoice',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='invoice' AND record_id=i.id ORDER BY revision DESC LIMIT 1),'{}')),'prices',json(COALESCE((SELECT json_group_object(p.price_id, json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='price' AND record_id=p.price_id ORDER BY revision DESC LIMIT 1),'{}'))) FROM (SELECT DISTINCT price_id FROM nc_invoice_lines WHERE invoice_id=i.id AND price_id IS NOT NULL ORDER BY price_id) p),'{}')),'payments',json(COALESCE((SELECT json_group_object(a.payment_id, json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='payment' AND record_id=a.payment_id ORDER BY revision DESC LIMIT 1),'{}'))) FROM (SELECT DISTINCT payment_id FROM nc_allocations WHERE invoice_id=i.id ORDER BY payment_id) a),'{}')),'credit_notes',json(COALESCE((SELECT json_group_object(c.id, json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='credit-note' AND record_id=c.id ORDER BY revision DESC LIMIT 1),'{}'))) FROM nc_credit_notes c WHERE c.invoice_id=i.id),'{}'))))),e.ms
 FROM (SELECT 'evt_'||lower(hex(randomblob(12))) AS eid,CAST((julianday('now')-2440587.5)*86400000 AS INTEGER) AS ms) e, nc_invoices i
 WHERE i.id=NEW.invoice_id AND i.status='issued' AND i.total_cents>0 AND (i.total_cents - COALESCE((SELECT SUM(COALESCE(applied_cents,amount_cents)) FROM nc_credit_notes WHERE invoice_id = i.id), 0) - COALESCE((SELECT SUM(amount_cents) FROM nc_allocations WHERE invoice_id = i.id), 0) - COALESCE((SELECT SUM(amount_cents) FROM nc_usage_credit_applications WHERE invoice_id=i.id),0) - (COALESCE((SELECT SUM(amount_cents) FROM nc_write_offs WHERE invoice_id=i.id AND status='executed'),0) - COALESCE((SELECT SUM(amount_cents) FROM nc_write_off_recoveries WHERE invoice_id=i.id),0)) - COALESCE((SELECT SUM(amount_cents) FROM nc_balance_entries WHERE kind='application' AND grant_id IS NOT NULL AND invoice_id=i.id),0))<=0 AND NOT EXISTS(SELECT 1 FROM nc_webhook_events x WHERE x.kind='invoice.paid' AND x.record_id=i.id);
END;
CREATE TRIGGER nc_webhook_invoice_paid_balance AFTER INSERT ON nc_balance_entries WHEN NEW.kind='application' AND NOT EXISTS(SELECT 1 FROM nc_privacy_context) AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) AND EXISTS(SELECT 1 FROM nc_webhook_endpoints WHERE status='active') BEGIN
 INSERT INTO nc_webhook_events(id,kind,customer_id,record_id,payload_json,created_at)
 SELECT e.eid,'invoice.paid',i.customer_id,i.id,json_object('id',e.eid,'object','event','type','invoice.paid','created',e.ms/1000,'data',json_object('object',json_object('id',i.id,'object','invoice','number',i.number,'customer_id',i.customer_id,'subscription_id',i.subscription_id,'status',i.status,'period_start',i.period_start,'period_end',i.period_end,'issue_date',i.issue_date,'due_date',i.due_date,'subtotal_cents',i.subtotal_cents,'tax_cents',i.tax_cents,'total_cents',i.total_cents,'currency',i.currency,'billing_entity_id',i.billing_entity_id,'amount_paid_cents',COALESCE((SELECT SUM(amount_cents) FROM nc_allocations WHERE invoice_id=i.id),0),'amount_remaining_cents',0),'metadata',json_object('customer',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='customer' AND record_id=i.customer_id ORDER BY revision DESC LIMIT 1),'{}')),'subscription',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='subscription' AND record_id=i.subscription_id ORDER BY revision DESC LIMIT 1),'{}')),'invoice',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='invoice' AND record_id=i.id ORDER BY revision DESC LIMIT 1),'{}')),'prices',json(COALESCE((SELECT json_group_object(p.price_id, json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='price' AND record_id=p.price_id ORDER BY revision DESC LIMIT 1),'{}'))) FROM (SELECT DISTINCT price_id FROM nc_invoice_lines WHERE invoice_id=i.id AND price_id IS NOT NULL ORDER BY price_id) p),'{}')),'payments',json(COALESCE((SELECT json_group_object(a.payment_id, json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='payment' AND record_id=a.payment_id ORDER BY revision DESC LIMIT 1),'{}'))) FROM (SELECT DISTINCT payment_id FROM nc_allocations WHERE invoice_id=i.id ORDER BY payment_id) a),'{}')),'credit_notes',json(COALESCE((SELECT json_group_object(c.id, json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='credit-note' AND record_id=c.id ORDER BY revision DESC LIMIT 1),'{}'))) FROM nc_credit_notes c WHERE c.invoice_id=i.id),'{}'))))),e.ms
 FROM (SELECT 'evt_'||lower(hex(randomblob(12))) AS eid,CAST((julianday('now')-2440587.5)*86400000 AS INTEGER) AS ms) e, nc_invoices i
 WHERE i.id=NEW.invoice_id AND i.status='issued' AND i.total_cents>0 AND (i.total_cents - COALESCE((SELECT SUM(COALESCE(applied_cents,amount_cents)) FROM nc_credit_notes WHERE invoice_id = i.id), 0) - COALESCE((SELECT SUM(amount_cents) FROM nc_allocations WHERE invoice_id = i.id), 0) - COALESCE((SELECT SUM(amount_cents) FROM nc_usage_credit_applications WHERE invoice_id=i.id),0) - (COALESCE((SELECT SUM(amount_cents) FROM nc_write_offs WHERE invoice_id=i.id AND status='executed'),0) - COALESCE((SELECT SUM(amount_cents) FROM nc_write_off_recoveries WHERE invoice_id=i.id),0)) - COALESCE((SELECT SUM(amount_cents) FROM nc_balance_entries WHERE kind='application' AND grant_id IS NOT NULL AND invoice_id=i.id),0))<=0 AND NOT EXISTS(SELECT 1 FROM nc_webhook_events x WHERE x.kind='invoice.paid' AND x.record_id=i.id);
END;
CREATE TRIGGER nc_webhook_payment_recorded AFTER INSERT ON nc_payments WHEN NOT EXISTS(SELECT 1 FROM nc_privacy_context) AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) AND EXISTS(SELECT 1 FROM nc_webhook_endpoints WHERE status='active') BEGIN
 INSERT INTO nc_webhook_events(id,kind,customer_id,record_id,payload_json,created_at)
 SELECT e.eid,'payment.recorded',NEW.customer_id,NEW.id,json_object('id',e.eid,'object','event','type','payment.recorded','created',e.ms/1000,'data',json_object('object',json_object('id',NEW.id,'object','payment','customer_id',NEW.customer_id,'amount_cents',NEW.amount_cents,'currency','USD','received_on',NEW.received_on,'method',NEW.method,'reference',NEW.reference),'metadata',json_object('customer',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='customer' AND record_id=NEW.customer_id ORDER BY revision DESC LIMIT 1),'{}')),'payment',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='payment' AND record_id=NEW.id ORDER BY revision DESC LIMIT 1),'{}'))))),e.ms
 FROM (SELECT 'evt_'||lower(hex(randomblob(12))) AS eid,CAST((julianday('now')-2440587.5)*86400000 AS INTEGER) AS ms) e;
END;
CREATE TRIGGER nc_webhook_payment_failed AFTER UPDATE OF status ON nc_native_collections WHEN NEW.status IN ('declined','customer_action_required') AND OLD.status NOT IN ('declined','customer_action_required') AND NOT EXISTS(SELECT 1 FROM nc_privacy_context) AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) AND EXISTS(SELECT 1 FROM nc_webhook_endpoints WHERE status='active') BEGIN
 INSERT INTO nc_webhook_events(id,kind,customer_id,record_id,payload_json,created_at)
 SELECT e.eid,'payment.failed',NEW.customer_id,NEW.id,json_object('id',e.eid,'object','event','type','payment.failed','created',e.ms/1000,'data',json_object('object',json_object('id',NEW.id,'object','payment_attempt','invoice_id',NEW.invoice_id,'customer_id',NEW.customer_id,'amount_cents',NEW.amount_cents,'currency','USD','status',NEW.status,'error_code',NEW.error_code),'metadata',json_object('customer',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='customer' AND record_id=NEW.customer_id ORDER BY revision DESC LIMIT 1),'{}')),'invoice',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='invoice' AND record_id=NEW.invoice_id ORDER BY revision DESC LIMIT 1),'{}'))))),e.ms
 FROM (SELECT 'evt_'||lower(hex(randomblob(12))) AS eid,CAST((julianday('now')-2440587.5)*86400000 AS INTEGER) AS ms) e;
END;
CREATE TRIGGER nc_webhook_credit_note_created AFTER INSERT ON nc_credit_notes WHEN NOT EXISTS(SELECT 1 FROM nc_privacy_context) AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) AND EXISTS(SELECT 1 FROM nc_webhook_endpoints WHERE status='active') BEGIN
 INSERT INTO nc_webhook_events(id,kind,customer_id,record_id,payload_json,created_at)
 SELECT e.eid,'credit_note.created',NEW.customer_id,NEW.id,json_object('id',e.eid,'object','event','type','credit_note.created','created',e.ms/1000,'data',json_object('object',json_object('id',NEW.id,'object','credit_note','number',NEW.number,'invoice_id',NEW.invoice_id,'customer_id',NEW.customer_id,'amount_cents',NEW.amount_cents,'applied_cents',NEW.applied_cents,'subtotal_cents',NEW.subtotal_cents,'tax_cents',NEW.tax_cents,'currency','USD'),'metadata',json_object('customer',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='customer' AND record_id=NEW.customer_id ORDER BY revision DESC LIMIT 1),'{}')),'invoice',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='invoice' AND record_id=NEW.invoice_id ORDER BY revision DESC LIMIT 1),'{}')),'credit_note',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='credit-note' AND record_id=NEW.id ORDER BY revision DESC LIMIT 1),'{}'))))),e.ms
 FROM (SELECT 'evt_'||lower(hex(randomblob(12))) AS eid,CAST((julianday('now')-2440587.5)*86400000 AS INTEGER) AS ms) e;
END;
CREATE TRIGGER nc_webhook_customer_balance AFTER INSERT ON nc_balance_entries WHEN NOT EXISTS(SELECT 1 FROM nc_privacy_context) AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) AND EXISTS(SELECT 1 FROM nc_webhook_endpoints WHERE status='active') BEGIN
 INSERT INTO nc_webhook_events(id,kind,customer_id,record_id,payload_json,created_at)
 SELECT e.eid,'customer_balance.updated',NEW.customer_id,NEW.id,json_object('id',e.eid,'object','event','type','customer_balance.updated','created',e.ms/1000,'data',json_object('object',json_object('id',NEW.id,'object','balance_entry','customer_id',NEW.customer_id,'kind',NEW.kind,'amount_cents',NEW.amount_cents,'currency','USD','invoice_id',NEW.invoice_id,'payment_id',NEW.payment_id),'metadata',json_object('customer',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='customer' AND record_id=NEW.customer_id ORDER BY revision DESC LIMIT 1),'{}'))))),e.ms
 FROM (SELECT 'evt_'||lower(hex(randomblob(12))) AS eid,CAST((julianday('now')-2440587.5)*86400000 AS INTEGER) AS ms) e;
