CREATE TRIGGER nc_entitlement_dirty_subscription_insert AFTER INSERT ON nc_subscriptions WHEN NOT EXISTS(SELECT 1 FROM nc_privacy_context) AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) AND EXISTS(SELECT 1 FROM nc_webhook_endpoints WHERE status='active') BEGIN
 INSERT OR IGNORE INTO nc_entitlement_dirty(customer_id,marked_at) VALUES(NEW.customer_id,CAST((julianday('now')-2440587.5)*86400000 AS INTEGER));
END;
CREATE TRIGGER nc_entitlement_dirty_subscription_update AFTER UPDATE ON nc_subscriptions WHEN OLD.revision IS NOT NEW.revision AND NOT EXISTS(SELECT 1 FROM nc_privacy_context) AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) AND EXISTS(SELECT 1 FROM nc_webhook_endpoints WHERE status='active') BEGIN
 INSERT OR IGNORE INTO nc_entitlement_dirty(customer_id,marked_at) VALUES(NEW.customer_id,CAST((julianday('now')-2440587.5)*86400000 AS INTEGER));
END;
CREATE TRIGGER nc_entitlement_dirty_items AFTER INSERT ON nc_items WHEN NOT EXISTS(SELECT 1 FROM nc_privacy_context) AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) AND EXISTS(SELECT 1 FROM nc_webhook_endpoints WHERE status='active') BEGIN
 INSERT OR IGNORE INTO nc_entitlement_dirty(customer_id,marked_at) SELECT customer_id,CAST((julianday('now')-2440587.5)*86400000 AS INTEGER) FROM nc_subscriptions WHERE id=NEW.subscription_id;
END;
CREATE TRIGGER nc_entitlement_dirty_lifecycle AFTER INSERT ON nc_subscription_lifecycle WHEN NOT EXISTS(SELECT 1 FROM nc_privacy_context) AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) AND EXISTS(SELECT 1 FROM nc_webhook_endpoints WHERE status='active') BEGIN
 INSERT OR IGNORE INTO nc_entitlement_dirty(customer_id,marked_at) SELECT customer_id,CAST((julianday('now')-2440587.5)*86400000 AS INTEGER) FROM nc_subscriptions WHERE id=NEW.subscription_id;
END;
CREATE TRIGGER nc_entitlement_dirty_feature_granted AFTER INSERT ON nc_features WHEN NOT EXISTS(SELECT 1 FROM nc_privacy_context) AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) AND EXISTS(SELECT 1 FROM nc_webhook_endpoints WHERE status='active') BEGIN
 INSERT OR IGNORE INTO nc_entitlement_dirty(customer_id,marked_at) SELECT DISTINCT s.customer_id,CAST((julianday('now')-2440587.5)*86400000 AS INTEGER) FROM nc_subscriptions s JOIN nc_items i ON i.subscription_id=s.id JOIN nc_prices p ON p.id=i.price_id WHERE p.product_id=NEW.product_id;
END;
CREATE TRIGGER nc_entitlement_dirty_feature_removed AFTER DELETE ON nc_features WHEN NOT EXISTS(SELECT 1 FROM nc_privacy_context) AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) AND EXISTS(SELECT 1 FROM nc_webhook_endpoints WHERE status='active') BEGIN
 INSERT OR IGNORE INTO nc_entitlement_dirty(customer_id,marked_at) SELECT DISTINCT s.customer_id,CAST((julianday('now')-2440587.5)*86400000 AS INTEGER) FROM nc_subscriptions s JOIN nc_items i ON i.subscription_id=s.id JOIN nc_prices p ON p.id=i.price_id WHERE p.product_id=OLD.product_id;
END;
-- INT-003: members choose failed-delivery email; the alert custody table gains the event.
ALTER TABLE nc_notification_preferences ADD COLUMN webhook_failures INTEGER NOT NULL DEFAULT 0 CHECK(webhook_failures IN (0,1));
PRAGMA defer_foreign_keys = ON;
CREATE TABLE nc_notifications_next(
 event TEXT NOT NULL CHECK(event IN ('payment_mismatch','billrun_exceptions','proposals','webhook_failures')),
 subject TEXT NOT NULL,href TEXT NOT NULL,member_id TEXT NOT NULL REFERENCES nc_members(id),email TEXT NOT NULL,
 status TEXT NOT NULL CHECK(status IN ('pending','sending','accepted','suppressed','failed','rejected','uncertain')),provider_ref TEXT,updated_at INTEGER NOT NULL,
 PRIMARY KEY(event,subject,member_id));
INSERT INTO nc_notifications_next(event,subject,href,member_id,email,status,provider_ref,updated_at) SELECT event,subject,href,member_id,email,status,provider_ref,updated_at FROM nc_notifications;
DROP TABLE nc_notifications;
ALTER TABLE nc_notifications_next RENAME TO nc_notifications;
PRAGMA defer_foreign_keys = OFF;
CREATE TRIGGER nc_notifications_content BEFORE UPDATE OF event,subject,href,member_id,email ON nc_notifications WHEN NOT EXISTS(SELECT 1 FROM nc_privacy_context) BEGIN SELECT RAISE(ABORT, 'nectar_immutable'); END;
CREATE TRIGGER nc_notifications_keep BEFORE DELETE ON nc_notifications WHEN NOT EXISTS(SELECT 1 FROM nc_privacy_context) BEGIN SELECT RAISE(ABORT, 'nectar_immutable'); END;
CREATE TRIGGER nc_privacy_generation_nc_notifications_insert AFTER INSERT ON nc_notifications BEGIN UPDATE nc_privacy_generation SET value=value+1 WHERE id=1; END;
CREATE TRIGGER nc_privacy_generation_nc_notifications_update AFTER UPDATE ON nc_notifications BEGIN UPDATE nc_privacy_generation SET value=value+1 WHERE id=1; END;
CREATE TRIGGER nc_privacy_generation_nc_notifications_delete AFTER DELETE ON nc_notifications BEGIN UPDATE nc_privacy_generation SET value=value+1 WHERE id=1; END;
